// One item per account the product is being listed on. Each carries the
// account id, because the credentials are per account, not per platform.
const body = $input.first().json.body;
const product = body.product;
const wanted = body.payload.account_ids ?? [];

return product.listings
  .filter((l) => wanted.includes(l.account_id))
  .map((l) => ({ json: {
    product_id: product.id,
    account_id: l.account_id,
    platform: l.platform,
    label: l.label,
    external_id: l.external_id ?? null,
    action: l.external_id ? 'update' : 'create',
    product: {
      sku: product.sku,
      name: product.name,
      description: product.description,
      price: Number(product.price),
      currency: product.currency,
      stock: product.stock,
      weight_kg: Number(product.weight_kg),
      images: product.images ?? [],
      meta: (product.platform_meta ?? {})[l.platform] ?? {},
    },
  } }));

// Shopee: add_item to create, update_item to change one. Both are signed
//   partner_id + api_path + timestamp + access_token + shop_id
// with HMAC-SHA256 under the partner key.
const crypto = require('crypto');

const item = $input.item.json;
const creds = $('Get Account Credentials').item.json.credentials;
const account = $('Get Account Credentials').item.json.account;
const host = creds.host || ($env.SHOPEE_HOST || 'https://partner.shopeemobile.com');

const p = item.product;
const create = item.action === 'create';
const path = create ? '/api/v2/product/add_item' : '/api/v2/product/update_item';
const timestamp = Math.floor(Date.now() / 1000);
const base = `${creds.partner_id}${path}${timestamp}${creds.access_token}${creds.shop_id}`;
const sign = crypto.createHmac('sha256', creds.partner_key).update(base).digest('hex');

// Shopee prices in the shop's own currency, as a plain number.
const common = {
  item_name: p.name.slice(0, 120),
  description: p.description.slice(0, 3000),
  item_sku: p.sku,
  original_price: p.price,
  normal_stock: p.stock,
  weight: p.weight_kg,
  image: { image_id_list: p.meta.image_ids ?? [], image_url_list: p.images },
};

const payload = create
  ? {
      ...common,
      category_id: Number(p.meta.category_id),
      // Shopee refuses a listing with no channel to ship it on.
      logistic_info: (p.meta.logistic_ids ?? []).map((id) => ({
        logistic_id: Number(id), enabled: true,
      })),
      attribute_list: p.meta.attributes ?? [],
      ...(p.meta.brand_id ? { brand: { brand_id: Number(p.meta.brand_id) } } : {}),
      ...(p.meta.dimension ? { dimension: p.meta.dimension } : {}),
      condition: p.meta.condition ?? 'NEW',
      item_status: 'NORMAL',
    }
  : { item_id: Number(item.external_id), ...common };

return [{ json: {
  ...item,
  url: `${host}${path}?partner_id=${creds.partner_id}&timestamp=${timestamp}`
     + `&access_token=${creds.access_token}&shop_id=${creds.shop_id}&sign=${sign}`,
  payload,
  account_label: account.label,
} }];

const res = $input.item.json;
const ok = res.statusCode === 200 && !(res.body && res.body.error);
return [{ json: {
  product_id: res.product_id,
  account_id: res.account_id,
  state: ok ? 'LISTED' : 'FAILED',
  external_id: ok ? (String(res.body?.response?.item_id ?? $('Build Shopee Item').item.json.external_id ?? '')) : null,
  error: ok ? null : ('Shopee refused it: ' + String(JSON.stringify(res.body ?? {})).slice(0, 240)),
} }];

// Lazada: /product/create and /product/update, both taking an XML payload.
// The signature is HMAC-SHA256 over the api path followed by every parameter
// sorted by name and concatenated as name+value, upper-case hex.
const crypto = require('crypto');

const item = $input.item.json;
const creds = $('Get Account Credentials').item.json.credentials;
const account = $('Get Account Credentials').item.json.account;
const region = (account.region || 'PH').toLowerCase();
const hostByRegion = {
  ph: 'https://api.lazada.com.ph/rest', sg: 'https://api.lazada.sg/rest',
  my: 'https://api.lazada.com.my/rest', th: 'https://api.lazada.co.th/rest',
  id: 'https://api.lazada.co.id/rest', vn: 'https://api.lazada.vn/rest',
};
const host = creds.host || hostByRegion[region] || hostByRegion.ph;

const esc = (value) => String(value)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const p = item.product;
const create = item.action === 'create';
const path = create ? '/product/create' : '/product/update';

// Lazada takes the product as XML, not JSON.
const images = (p.images ?? []).map((url) => `<Image>${esc(url)}</Image>`).join('');
const attributes = Object.entries(p.meta.attributes ?? {})
  .map(([name, value]) => `<${name}>${esc(value)}</${name}>`).join('');
const payload = `<?xml version="1.0" encoding="UTF-8"?>
<Request><Product>
  ${create ? '' : `<ItemId>${esc(item.external_id)}</ItemId>`}
  <PrimaryCategory>${esc(p.meta.category_id ?? '')}</PrimaryCategory>
  <Images>${images}</Images>
  <Attributes>
    <name>${esc(p.name)}</name>
    <description>${esc(p.description)}</description>
    <brand>${esc(p.meta.brand ?? 'No Brand')}</brand>
    ${attributes}
  </Attributes>
  <Skus><Sku>
    <SellerSku>${esc(p.sku)}</SellerSku>
    <quantity>${p.stock}</quantity>
    <price>${p.price}</price>
    <package_weight>${p.weight_kg}</package_weight>
    <package_length>${esc(p.meta.length_cm ?? 10)}</package_length>
    <package_width>${esc(p.meta.width_cm ?? 10)}</package_width>
    <package_height>${esc(p.meta.height_cm ?? 10)}</package_height>
    <Images>${images}</Images>
  </Sku></Skus>
</Product></Request>`;

const params = {
  app_key: creds.app_key,
  access_token: creds.access_token,
  sign_method: 'sha256',
  timestamp: String(Date.now()),
  payload,
};
const base = path + Object.keys(params).sort()
  .map((name) => name + params[name]).join('');
const sign = crypto.createHmac('sha256', creds.app_secret)
  .update(base).digest('hex').toUpperCase();

const query = new URLSearchParams({ ...params, sign });
return [{ json: {
  ...item,
  url: `${host}${path}`,
  form: Object.fromEntries(query),
  account_label: account.label,
} }];

const res = $input.item.json;
const ok = res.statusCode === 200 && (res.body?.code === '0' || res.body?.code === 0);
return [{ json: {
  product_id: res.product_id,
  account_id: res.account_id,
  state: ok ? 'LISTED' : 'FAILED',
  external_id: ok ? (String(res.body?.data?.item_id ?? $('Build Lazada Product').item.json.external_id ?? '')) : null,
  error: ok ? null : ('Lazada refused it: ' + String((res.body?.detail?.[0]?.message ?? res.body?.message ?? JSON.stringify(res.body ?? {}))).slice(0, 240)),
} }];

// TikTok Shop: products/202309. Signed over the sorted query parameters
// wrapped in the app secret, with the body appended.
const crypto = require('crypto');

const item = $input.item.json;
const creds = $('Get Account Credentials').item.json.credentials;
const account = $('Get Account Credentials').item.json.account;
const host = creds.host || 'https://open-api.tiktokglobalshop.com';

const p = item.product;
const create = item.action === 'create';
const path = create ? '/product/202309/products' : `/product/202309/products/${item.external_id}`;

const body = JSON.stringify({
  title: p.name.slice(0, 255),
  description: `<p>${p.description}</p>`,
  category_id: String(p.meta.category_id ?? ''),
  brand_id: p.meta.brand_id ? String(p.meta.brand_id) : undefined,
  main_images: (p.images ?? []).map((uri) => ({ uri })),
  skus: [{
    seller_sku: p.sku,
    price: { amount: String(p.price), currency: p.currency },
    inventory: [{ warehouse_id: String(p.meta.warehouse_id ?? ''), quantity: p.stock }],
  }],
  package_weight: { value: String(p.weight_kg), unit: 'KILOGRAM' },
});

const params = {
  app_key: creds.app_key,
  shop_cipher: creds.shop_cipher,
  timestamp: String(Math.floor(Date.now() / 1000)),
  version: '202309',
};
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const base = creds.app_secret + path + sorted + body + creds.app_secret;
const sign = crypto.createHmac('sha256', creds.app_secret).update(base).digest('hex');

const query = new URLSearchParams({ ...params, sign });
return [{ json: {
  ...item,
  url: `${host}${path}?${query}`,
  method: create ? 'POST' : 'PUT',
  payload: JSON.parse(body),
  access_token: creds.access_token,
  account_label: account.label,
} }];

const res = $input.item.json;
const ok = res.statusCode === 200 && (res.body?.code === 0);
return [{ json: {
  product_id: res.product_id,
  account_id: res.account_id,
  state: ok ? 'LISTED' : 'FAILED',
  external_id: ok ? (String(res.body?.data?.product_id ?? $('Build TikTok Shop Product').item.json.external_id ?? '')) : null,
  error: ok ? null : ('TikTok Shop refused it: ' + String((res.body?.message ?? JSON.stringify(res.body ?? {}))).slice(0, 240)),
} }];

// A marketplace nobody has wired a sender for yet.
const item = $('One Item Per Account').item.json;
return [{ json: {
  product_id: item.product_id,
  account_id: item.account_id,
  state: 'FAILED',
  error: 'No product sender is wired up for ' + item.platform + ' yet.',
} }];
